// Original synthesized audio. Starts only after a user gesture.
export class FieldAudio{
 constructor(){this.ctx=null;this.levels={master:.65,effects:.7,music:.25};this.voices={};this.muted=false;}
 start(){try{if(!this.ctx){const C=globalThis.AudioContext||globalThis.webkitAudioContext;if(!C)return;this.ctx=new C();this.master=this.ctx.createGain();this.master.connect(this.ctx.destination);this.fx=this.ctx.createGain();this.fx.connect(this.master);this.music=this.ctx.createGain();this.music.connect(this.master);for(const [name,type,freq]of [['motor','sawtooth',65],['rotor','triangle',95],['machine','triangle',60]]){const o=this.ctx.createOscillator(),g=this.ctx.createGain();o.type=type;o.frequency.value=freq;g.gain.value=0;o.connect(g);g.connect(this.fx);o.start();this.voices[name]={o,g};}const buffer=this.ctx.createBuffer(1,this.ctx.sampleRate*2,this.ctx.sampleRate),samples=buffer.getChannelData(0);for(let i=0;i<samples.length;i++)samples[i]=Math.random()*2-1;const noise=this.ctx.createBufferSource(),filter=this.ctx.createBiquadFilter(),windGain=this.ctx.createGain();noise.buffer=buffer;noise.loop=true;filter.type='lowpass';filter.frequency.value=420;windGain.gain.value=0;noise.connect(filter);filter.connect(windGain);windGain.connect(this.fx);noise.start();this.voices.wind={o:noise,g:windGain};for(const f of [55,82.41,110.12]){const o=this.ctx.createOscillator(),g=this.ctx.createGain();o.type='sine';o.frequency.value=f;g.gain.value=.035;o.connect(g);g.connect(this.music);o.start();}}this.ctx.resume()?.catch(()=>{});}catch{this.ctx=null;}}
 setLevels(levels){this.levels={...this.levels,...levels};}
 pause(paused){this.muted=paused;if(this.ctx)this.master.gain.setTargetAtTime(this.levels.master,this.ctx.currentTime,.08);}
 event(name){if(!this.ctx)return;const sounds={ui:[620,.05],scan:[1200,.22],drone:[240,.3],use:[380,.1],craft:[780,.2],shot:[75,.12],pulse:[180,.25],hit:[100,.16],save:[960,.13],radio:[440,.16],fail:[120,.3],success:[880,.4]};const [f,d]=sounds[name]||sounds.use,c=this.ctx,o=c.createOscillator(),g=c.createGain();o.type=['shot','hit','fail'].includes(name)?'sawtooth':'sine';o.frequency.setValueAtTime(f,c.currentTime);o.frequency.exponentialRampToValueAtTime(Math.max(30,f*(name==='scan'?1.8:.55)),c.currentTime+d);g.gain.setValueAtTime(.0001,c.currentTime);g.gain.exponentialRampToValueAtTime(name==='ui'?.045:.12,c.currentTime+.01);g.gain.exponentialRampToValueAtTime(.0001,c.currentTime+d);o.connect(g);g.connect(this.fx);o.start();o.stop(c.currentTime+d+.02);o.onended=()=>{o.disconnect();g.disconnect();};}
 update(s,paused,flowing){if(!this.ctx)return;const c=this.ctx,t=c.currentTime;this.master.gain.setTargetAtTime(this.levels.master,t,.1);this.fx.gain.setTargetAtTime(this.levels.effects,t,.1);this.music.gain.setTargetAtTime(paused?0:this.levels.music,t,.1);const moving=Math.min(1,Math.abs(s.speed)/30);const levels={motor:s.mode==='bike'&&s.battery>0&&s.powerMode!=='HUMAN'?moving*.045:0,rotor:s.mode==='drone'?.07:(s.scanTime>0?.018:0),wind:.008+moving*.016,machine:s.harvesting||flowing?.045:0};for(const [k,v]of Object.entries(this.voices)){v.g.gain.setTargetAtTime(paused?0:levels[k],t,.12);if(k==='motor')v.o.frequency.setTargetAtTime(55+moving*140,t,.1);if(k==='rotor')v.o.frequency.setTargetAtTime(95+Math.sin(t*7)*9,t,.1);}if(!paused&&moving>.1&&s.mode==='foot'&&(!this.lastStep||t-this.lastStep>.42)){this.lastStep=t;this.event('use');}if(!paused&&s.powerMode==='HUMAN'&&moving>.05&&(!this.lastChain||t-this.lastChain>.3)){this.lastChain=t;this.event('ui');}}
}
